<div class="customer-modal-backdrop stock-form-backdrop" role="presentation"><section class="estimate-side-panel stock-side-panel" role="dialog" aria-modal="true"><div class="estimate-panel-header"><div><h2>Record Payment</h2><span><?= e($purchase['purchase_no']) ?></span></div><a href="index.php?page=admin&amp;section=stock-purchases">&times;</a></div><div class="estimate-panel-body"><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><div class="restock-item-summary"><div><span>Total Amount</span><strong>Rs. <?= number_format((float)$purchase['total_amount'],2) ?></strong></div><div><span>Already Paid</span><strong>Rs. <?= number_format((float)$purchase['paid_amount'],2) ?></strong></div><div><span>Balance Due</span><strong>Rs. <?= number_format((float)$purchase['balance_amount'],2) ?></strong></div><div><span>Supplier</span><strong><?= e($purchase['supplier_name']?:'No supplier') ?></strong></div></div><form method="post" action="index.php?page=admin&amp;section=stock-purchase-pay&amp;id=<?= (int)$purchase['id'] ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="estimate-form-section"><label class="form-label">Payment Amount (Rs.) *</label><input class="form-control" type="number" name="payment_amount" min="0.01" max="<?= e((string)$purchase['balance_amount']) ?>" step="0.01" required placeholder="Enter payment amount"><small class="bay-field-hint">Maximum payment: Rs. <?= number_format((float)$purchase['balance_amount'],2) ?></small></div><div class="estimate-form-section"><label class="form-label">Payment Method</label><select class="form-select" name="payment_method"><?php foreach (['cash' => 'Cash (cash drawer)', 'bank_transfer' => 'Bank transfer', 'card' => 'Card', 'cheque' => 'Cheque'] as $method => $label): ?><option value="<?= e($method) ?>" <?= ($input['payment_method'] ?? $_POST['payment_method'] ?? 'cash') === $method ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><small class="bay-field-hint">Cash payments reduce the paying cashier's expected closing cash.</small></div><div class="estimate-form-footer"><a class="btn btn-light" href="index.php?page=admin&amp;section=stock-purchases">Cancel</a><button class="btn btn-danger" type="submit">Save Payment</button></div></form></div></section></div>
